#!/usr/bin/env bash
# Derive the broker-free catalogue CI entrypoint from the production signed-fix workflow.
# Pull-request CI may not grant id-token: write (.github/tests/test-ci-idtoken-boundary.sh), and
# GitHub refuses a call whose caller grants less than a called job asks for, even when that job
# never runs. So catalogue CI calls this projection instead: production with its display name
# changed and the apply-fixes job's id-token grant removed. Its steps are exactly production's;
# the CI calls never reach the signing step, and without the grant it could not reach the broker.
set -euo pipefail
root="$(cd "$(dirname "$0")/../.." && pwd)"
source="${1:-$root/.github/workflows/apply-signed-fixes.yaml}"
destination="${2:-$root/.github/workflows/apply-signed-fixes-ci.yaml}"
work="$(mktemp)"
trap 'rm -f "$work"' EXIT
yq '
  .name = (.name + " (Broker-free CI)") |
  del(.jobs["apply-fixes"].permissions["id-token"])
' "$source" >"$work"
{
  printf '# Generated by .github/scripts/generate-apply-signed-fixes-ci.sh; do not edit.\n'
  cat "$work"
} >"$destination"
